package com.moishow.identity;

import com.moishow.MoishowServerApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.context.annotation.*;
import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.core.annotation.Order;
import org.springframework.web.cors.*;import org.springframework.web.servlet.config.annotation.*;
import org.testcontainers.postgresql.PostgreSQLContainer;import tools.jackson.databind.*;
import java.net.*;import java.net.http.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;

/** Explicit test-source-only host. No production login or production profile is changed. */
public class MobileScenarioHost {
 static final Map<String,String> codes=new ConcurrentHashMap<>();static final ObjectMapper json=new ObjectMapper();
 static final HttpClient http=HttpClient.newHttpClient();static String base="http://127.0.0.1:18080/api/v1";
 @Configuration @Profile("mobile-scenario") static class Fixtures implements WebMvcConfigurer {
  @Bean @Primary SocialVerifier fixtureIdentity(){return (provider,token,nonce)->{ApiProblem.require(token.startsWith("mobile-scenario:"),401,"SCENARIO_IDENTITY_REQUIRED");return new SocialVerifier.Identity(provider,token.substring(16));};}
  @Bean @Primary SmsGateway captureSms(){return (phone,code)->codes.put(phone,code);}
  @Bean @Primary BankOwnershipVerifier fixtureBank(){return (user,bank,number,holder)->"LOCAL_SCENARIO_PROOF";}
  @Override public void addCorsMappings(CorsRegistry registry){registry.addMapping("/api/v1/**").allowedOrigins("http://127.0.0.1:8766","http://127.0.0.1:5173").allowedMethods("GET","POST","DELETE","OPTIONS").allowedHeaders("Authorization","Content-Type","Idempotency-Key");}
  @Bean @Order(0) SecurityFilterChain scenarioPreflight(HttpSecurity http)throws Exception{return http.securityMatcher(r->r.getMethod().equals("OPTIONS")&&r.getRequestURI().startsWith("/api/v1/")).cors(cors->cors.configurationSource(request->{var c=new CorsConfiguration();c.setAllowedOrigins(List.of("http://127.0.0.1:8766","http://127.0.0.1:5173"));c.setAllowedMethods(List.of("GET","POST","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","Idempotency-Key"));return c;})).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}
 }
 static JsonNode call(String method,String path,String token,Object body)throws Exception{var builder=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(30)).header("Content-Type","application/json");if(token!=null)builder.header("Authorization","Bearer "+token);if(method.equals("POST"))builder.header("Idempotency-Key",UUID.randomUUID().toString());builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));var result=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());if(result.statusCode()<200||result.statusCode()>=300)throw new IllegalStateException("Scenario HTTP "+method+" "+path+" returned "+result.statusCode());return json.readTree(result.body());}
 static JsonNode post(String path,String token,Object body)throws Exception{return call("POST",path,token,body);}static JsonNode get(String path,String token)throws Exception{return call("GET",path,token,null);}
 static Map<String,Object> user(String name,int index)throws Exception{var challenge=post("/auth/challenges",null,Map.of());var login=post("/auth/social",null,Map.of("provider","GOOGLE","token","mobile-scenario:"+name,"challengeId",challenge.path("challengeId").asText()));String pending=login.path("token").asText(),phone="+82109"+String.format("%07d",index);var sms=post("/auth/sms",pending,Map.of("phone",phone));post("/auth/sms/"+sms.path("id").asText()+"/verify",pending,Map.of("code",codes.get(phone)));var session=post("/auth/register",pending,Map.of("nickname",name,"verificationId",sms.path("id").asText()));return json.convertValue(session,Map.class);}
 static String token(Map<String,Object> user){return (String)user.get("token");}
 public static void main(String[] args)throws Exception{
  var postgres=new PostgreSQLContainer("postgres:17-alpine");postgres.start();var manifest=Path.of(System.getProperty("scenario.manifest","../../.superpowers/mobile-scenario/manifest.json")).toAbsolutePath().normalize();Files.createDirectories(manifest.getParent());
  var files=manifest.getParent().resolve("protected-files");Files.createDirectories(files);var aes=new byte[32];new java.security.SecureRandom().nextBytes(aes);
  var context=new SpringApplicationBuilder(MoishowServerApplication.class,Fixtures.class).profiles("db","dev","mobile-scenario").properties("server.address=127.0.0.1","server.port=18080","CHAT_ALLOWED_ORIGINS=http://127.0.0.1:8766","logging.level.root=ERROR","spring.main.banner-mode=off","FILE_STORAGE_MODE=LOCAL","FILE_STORAGE_ROOT="+files,"BANK_DATA_KEY_BASE64="+Base64.getEncoder().encodeToString(aes)).run("--spring.datasource.url="+postgres.getJdbcUrl(),"--spring.datasource.username="+postgres.getUsername(),"--spring.datasource.password="+postgres.getPassword());
  var stopRequest=manifest.getParent().resolve("shutdown.request");var stopReady=manifest.getParent().resolve("shutdown.ready");Files.deleteIfExists(stopRequest);
  Runtime.getRuntime().addShutdownHook(new Thread(()->{context.close();postgres.stop();try{Files.deleteIfExists(manifest);Files.deleteIfExists(stopReady);}catch(Exception ignored){}}));
  Thread.ofPlatform().daemon(true).name("scenario-local-shutdown").start(()->{try{while(true){if(Files.exists(stopRequest)){Files.deleteIfExists(stopRequest);System.exit(0);}Thread.sleep(500);}}catch(Exception e){Thread.currentThread().interrupt();}});
  var roles=new LinkedHashMap<String,Map<String,Object>>();String[] labels={"모임장","관리자","참가자","공개 번개 비부원","차단 이력 참가자","탈퇴 참가자","운영자","첫 대화 수신자"};for(int i=0;i<labels.length;i++)roles.put(labels[i],user(labels[i],i+1));String owner=token(roles.get(labels[0]));String club=post("/clubs",owner,Map.of("name","시나리오 산책 모임","joinMode","IMMEDIATE")).path("id").asText();
  for(int i:new int[]{1,2,4,5}){long version=get("/clubs/"+club,owner).path("version").asLong();post("/clubs/"+club+"/join",token(roles.get(labels[i])),Map.of("version",version,"nickname",labels[i]));}
  post("/clubs/"+club+"/members/"+roles.get(labels[1]).get("userId")+"/role",owner,Map.of("version",get("/clubs/"+club,owner).path("version").asLong(),"role","ADMIN"));
  var event=post("/clubs/"+club+"/events",owner,Map.of("version",get("/clubs/"+club,owner).path("version").asLong(),"title","오늘 함께 걷기","kind","LIGHTNING","publicEvent",true,"settlementMode","PREPAY","startsAt",Instant.now().minusSeconds(3600),"endsAt",Instant.now().plusSeconds(7200)));
  String eventId=event.path("id").asText();var round=post("/events/"+eventId+"/rounds",owner,Map.of("version",event.path("version").asLong(),"capacity",20,"closesAt",Instant.now().minusSeconds(1800),"cancellationFee",1000));String roundId=round.path("id").asText();
  for(int i:new int[]{0,2,3,4,5}){var latest=get("/events/"+eventId,owner).path("rounds").get(0);var participation=post("/rounds/"+roundId+"/participations",token(roles.get(labels[i])),Map.of("version",latest.path("version").asLong()));post("/rounds/"+roundId+"/participations/"+participation.path("id").asText()+"/approve",owner,Map.of("version",participation.path("version").asLong(),"reason","실제 본인 합류 요청 승인"));}
  long book=post("/events/"+eventId+"/finance/open",owner,Map.of("version",0,"mode","PREPAY")).path("version").asLong();post("/rounds/"+roundId+"/payment-requests",owner,Map.of("version",book,"amount",20000,"deadline",Instant.now().plusSeconds(86400)));
  post("/rounds/"+roundId+"/fee",owner,Map.of("version",get("/events/"+eventId,owner).path("rounds").get(0).path("version").asLong(),"cancellationFee",1500,"reason","고지 비용 변경 재동의 테스트"));
  post("/clubs/"+club+"/leave",token(roles.get(labels[5])),Map.of("version",get("/clubs/"+club,owner).path("version").asLong()));post("/clubs/"+club+"/members/"+roles.get(labels[4]).get("userId")+"/blacklist",owner,Map.of("version",get("/clubs/"+club,owner).path("version").asLong(),"enabled",true));
  var group=post("/chat/groups",owner,Map.of("title","주말 산책 그룹","userIds",List.of(roles.get(labels[1]).get("userId"),roles.get(labels[2]).get("userId"))));post("/chat/rooms/"+group.path("id").asText()+"/invitations/accept",token(roles.get(labels[1])),Map.of());post("/chat/direct",owner,Map.of("userId",roles.get(labels[7]).get("userId"),"body","처음 보내는 산책 대화 요청입니다."));
  var post=post("/feed/posts",owner,Map.of("clubId",club,"kind","NOTICE","body","이번 주 모임 공지입니다."));post("/reports",token(roles.get(labels[2])),Map.of("clubId",club,"targetUserId",roles.get(labels[0]).get("userId"),"type","CLUB_CONTENT","contentId",post.path("id").asText(),"contentType","POST","reason","실제 운영자 배정 검증용 테스트 신고"));context.getBean(org.springframework.jdbc.core.JdbcTemplate.class).update("insert into platform_operator(user_id,provisioned_by) values(cast(? as uuid),?)",roles.get(labels[6]).get("userId"),"TEST_ONLY_MOBILE_SCENARIO");
  var payload=new LinkedHashMap<String,Object>();payload.put("testOnly",true);payload.put("apiBaseUrl",base);payload.put("roles",roles);payload.put("clubId",club);payload.put("eventId",eventId);payload.put("roundId",roundId);Files.writeString(manifest,json.writeValueAsString(payload),StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);
  Files.writeString(stopReady,Long.toString(ProcessHandle.current().pid()));
  System.out.println("TEST scenario host ready on 127.0.0.1:18080; manifest written without printing credentials.");new CountDownLatch(1).await();
 }
}
